DOCUMENTS = [{'name': '01-relayops-source-of-truth.json', 'role': 'canonical', 'text': '{\n  "product_id": "relayops-pilot-v1",\n  "name": "RelayOps Webhook Delivery Console",\n  "version": "1.0",\n  "source_date": "2026-09-13",\n  "classification": "Fictional product scenario. Product-team characters, accounts, budgets and measurements are synthetic; the document author and actual reviewer are user-supplied identities.",\n  "metadata": {\n    "author": "Raghavendra Kaushik",\n    "reviewer": "",\n    "date": "2026-09-13",\n    "status": "In Review"\n  },\n  "overview": "A tenant-isolated desktop console that lets integration operators investigate failed webhook deliveries and replay eligible events without an engineering-owned script. A three-account pilot covers investigation, permission management, replay orchestration and audit history; the existing identity service and Delivery API v2 remain the systems of record.",\n  "problem": "Support currently collects an event identifier, asks an engineer to inspect logs, waits for an engineering script to replay the event, and asks again for the result. This creates repeated handoffs, weak operator visibility and inconsistent replay audit records.",\n  "business_goal": "Reduce the median elapsed time from a failed-delivery support report to a confirmed replay result from a synthetic baseline of 45 minutes to at most 15 minutes during the four-week pilot.",\n  "user_goal": "Enable authorized Integration Operators to find failures, inspect evidence, start one eligible replay and see its final outcome without requesting script access.",\n  "metrics": [\n    {\n      "name": "Median resolution time",\n      "baseline": "45 minutes across 20 fictional historical tickets",\n      "target": "At most 15 minutes",\n      "window": "Four-week pilot, 2026-10-12 through 2026-11-08",\n      "measurement": "Median of support_reported_at to replay_terminal_at for eligible resolved pilot tickets; report unresolved-ticket count separately to avoid survivor bias.",\n      "owner": "Noor Ali, Product Analytics"\n    },\n    {\n      "name": "Self-service completion rate",\n      "baseline": "0% in the fictional manual process",\n      "target": "At least 80% of eligible replay incidents completed without an engineer running a script",\n      "window": "Same four-week pilot",\n      "measurement": "Eligible completed incidents with operator-started replay divided by all eligible completed incidents; exclude ineligible 4xx failures and publish the exclusion count.",\n      "owner": "Noor Ali, Product Analytics"\n    },\n    {\n      "name": "Audit completeness",\n      "baseline": "60% of 20 fictional historical tickets have a traceable actor and outcome",\n      "target": "100% of accepted replay jobs have all required audit fields and a terminal or current state",\n      "window": "Daily checks throughout pilot",\n      "measurement": "Reconcile accepted replay_job_id values against append-only audit events; any missing identifier or actor fails release readiness.",\n      "owner": "Isha Shah, Security Engineering"\n    }\n  ],\n  "personas": [\n    {\n      "role": "Integration Operator",\n      "need": "Investigate and replay eligible failed deliveries in the operator\'s own account.",\n      "workaround": "Open a support ticket and ask engineering to run an internal replay script.",\n      "permissions": "Read delivery records; replay only when an Account Admin has explicitly granted replay permission."\n    },\n    {\n      "role": "Account Admin",\n      "need": "Control which operators may initiate replay within the admin\'s account.",\n      "workaround": "Ask the identity team to change role assignments manually.",\n      "permissions": "Grant or revoke operator replay permission; no cross-account administration."\n    },\n    {\n      "role": "Auditor",\n      "need": "Inspect delivery history and replay audit evidence within the auditor\'s account.",\n      "workaround": "Request CSV extracts from engineering and correlate ticket IDs manually.",\n      "permissions": "Read delivery and audit history only; cannot replay or change permissions."\n    }\n  ],\n  "epics": [\n    {\n      "id": "EP-01",\n      "title": "Investigate webhook delivery failures",\n      "outcome": "Operators can locate and inspect relevant delivery evidence."\n    },\n    {\n      "id": "EP-02",\n      "title": "Replay safely and observe outcomes",\n      "outcome": "Authorized operators can replay eligible failures once and see a durable result."\n    },\n    {\n      "id": "EP-03",\n      "title": "Control and audit account access",\n      "outcome": "Admins govern replay access and auditors can inspect immutable account-scoped evidence."\n    }\n  ],\n  "out_of_scope": [\n    "Bulk replay and scheduled replay",\n    "Creating or editing webhook endpoints",\n    "New webhook signing algorithms",\n    "Mobile and native applications",\n    "AI-generated failure explanations",\n    "Customer-facing CSV or spreadsheet export in the pilot"\n  ],\n  "assumptions": [\n    {\n      "statement": "The three fictional pilot accounts use the existing customer-account identity service and have no external SSO migration during this pilot.",\n      "owner": "Omar Khan, Identity Team",\n      "validation": "Verified in the synthetic pilot-readiness inventory on 2026-09-11."\n    },\n    {\n      "statement": "A replay reuses the original immutable event payload and existing signing configuration; it does not create or edit an event.",\n      "owner": "Leo Chen, Core Events",\n      "validation": "Recorded as decision DEC-02 and included in replay contract review."\n    },\n    {\n      "statement": "The synthetic workload of 100,000 delivery records per account and 500 concurrent operators is sufficient for pilot capacity testing.",\n      "owner": "Aditi Rao, Engineering Lead",\n      "validation": "Explicit pilot sizing decision; expansion beyond this envelope requires a new capacity review."\n    }\n  ],\n  "dependencies": [\n    {\n      "name": "Delivery API v2",\n      "owner": "Leo Chen, Core Events",\n      "status": "Existing API; pilot contract additions due 2026-09-25",\n      "risk": "Delayed status-query support prevents end-to-end replay observation.",\n      "mitigation": "Contract tests at integration start; feature flag remains off if readiness fails."\n    },\n    {\n      "name": "Replay-worker API",\n      "owner": "Leo Chen, Core Events",\n      "status": "Synthetic commitment: staging available 2026-09-25",\n      "risk": "Worker readiness is a critical-path dependency.",\n      "mitigation": "Daily contract smoke test from 2026-09-25; launch requires successful enqueue-to-terminal test."\n    },\n    {\n      "name": "Customer-account identity service",\n      "owner": "Omar Khan, Identity Team",\n      "status": "Existing service; replay-permission endpoint contract signed 2026-09-11",\n      "risk": "Stale role propagation could retain revoked access.",\n      "mitigation": "Every replay authorization checks current permission; revocations take effect within 60 seconds."\n    },\n    {\n      "name": "Append-only audit store",\n      "owner": "Isha Shah, Security Engineering",\n      "status": "Existing storage; retention policy configured by 2026-09-28",\n      "risk": "Audit write failure could create an untraceable replay.",\n      "mitigation": "Atomic outbox transaction records acceptance before dispatch; do not accept replay if transaction fails."\n    }\n  ],\n  "decisions": [\n    {\n      "id": "DEC-01",\n      "question": "Which delivery failures are eligible?",\n      "resolution": "Only network timeouts and HTTP 5xx failures from the previous 30 days are eligible. HTTP 4xx, successful and already-running deliveries are not eligible.",\n      "owner": "Maya Sen",\n      "date": "2026-09-11"\n    },\n    {\n      "id": "DEC-02",\n      "question": "What happens when a key is reused?",\n      "resolution": "Within 24 hours, the same account, delivery and Idempotency-Key with an identical body returns the original replay_job_id without another enqueue. Reusing the key with a different body returns HTTP 409.",\n      "owner": "Leo Chen",\n      "date": "2026-09-11"\n    },\n    {\n      "id": "DEC-03",\n      "question": "How often does job status refresh?",\n      "resolution": "The UI polls job status every 15 seconds only while the job is queued or running and the tab is visible. Polling stops on terminal status or hidden tab and refreshes immediately when the tab becomes visible. Manual refresh is available.",\n      "owner": "Aditi Rao",\n      "date": "2026-09-11"\n    },\n    {\n      "id": "DEC-04",\n      "question": "Is customer-facing export included?",\n      "resolution": "No customer-facing export in the pilot. Auditors use the account-scoped on-screen audit view.",\n      "owner": "Maya Sen",\n      "date": "2026-09-11"\n    },\n    {\n      "id": "DEC-05",\n      "question": "Who owns KPI reporting?",\n      "resolution": "Noor Ali owns daily dashboard reconciliation and the final four-week pilot report.",\n      "owner": "Maya Sen",\n      "date": "2026-09-11"\n    },\n    {\n      "id": "DEC-06",\n      "question": "Is the worker availability still unknown?",\n      "resolution": "The earlier discovery uncertainty is superseded by the synthetic Core Events commitment of staging availability on 2026-09-25. This is a sample scenario decision, not a real team commitment.",\n      "owner": "Leo Chen",\n      "date": "2026-09-11"\n    }\n  ],\n  "open_questions": {\n    "state": "resolved",\n    "statement": "All six product-scope questions raised in discovery were resolved in DEC-01 through DEC-06. Any new missing information or conflicting evidence reopens review and blocks PRD generation.",\n    "resolution_ids": [\n      "DEC-01",\n      "DEC-02",\n      "DEC-03",\n      "DEC-04",\n      "DEC-05",\n      "DEC-06"\n    ]\n  },\n  "timeline": [\n    {\n      "milestone": "Requirements and architecture review",\n      "date": "2026-09-18",\n      "owner": "Maya Sen and Aditi Rao",\n      "exit": "Reviewer approves source-backed requirements, API contracts and scope decisions."\n    },\n    {\n      "milestone": "Design Complete",\n      "date": "2026-09-21",\n      "owner": "Elena Park, Product Design",\n      "exit": "Desktop interaction and permission-error designs signed off."\n    },\n    {\n      "milestone": "Development Start",\n      "date": "2026-09-22",\n      "owner": "Aditi Rao",\n      "exit": "Sprint backlog accepted and mocked API contracts available."\n    },\n    {\n      "milestone": "Integration ready",\n      "date": "2026-09-28",\n      "owner": "Leo Chen",\n      "exit": "Identity, worker and audit integration contract tests pass."\n    },\n    {\n      "milestone": "QA / Testing",\n      "date": "2026-10-05",\n      "owner": "Ravi Menon, QA Lead",\n      "exit": "Functional, tenant-isolation, replay-deduplication, browser and capacity tests pass."\n    },\n    {\n      "milestone": "Launch",\n      "date": "2026-10-12",\n      "owner": "Maya Sen",\n      "exit": "Go/no-go approval; three account feature flags enabled; monitoring and rollback staffed."\n    },\n    {\n      "milestone": "Pilot review",\n      "date": "2026-11-09",\n      "owner": "Noor Ali",\n      "exit": "Four-week KPI report, incident review and rollout recommendation reviewed."\n    }\n  ],\n  "delivery": {\n    "budget": "Synthetic pilot engineering budget: USD 48,000, including a USD 3,000 infrastructure ceiling for the four-week pilot.",\n    "team": "One PM, one designer, two backend engineers, one frontend engineer and one QA engineer; security and identity owners provide part-time review.",\n    "rollout": "Enable the feature for exactly three fictional accounts, account-pilot-a, account-pilot-b and account-pilot-c, on 2026-10-12 after go/no-go approval.",\n    "rollback": "Disable replay controls using the per-account feature flag; continue read-only inspection and let already accepted jobs finish. Do not delete queued jobs or audit records.",\n    "support": "Core Events owns worker incidents; Identity owns authorization incidents; Security owns audit gaps. Maya coordinates the pilot incident review."\n  },\n  "requirements": [\n    {\n      "id": "FR-001",\n      "title": "Filter delivery history",\n      "epic_id": "EP-01",\n      "persona": "Integration Operator",\n      "want": "filter deliveries by status, endpoint, event type and date range",\n      "benefit": "I can locate relevant failed deliveries without searching engineering logs.",\n      "description": "Provide an account-scoped delivery list. Combine supplied filters with AND. Use UTC ISO 8601 date bounds, inclusive start and exclusive end. Limit the selected interval and record age to the previous 30 days. Paginate 50 records per page, ordered by timestamp descending and delivery ID descending as the tie-breaker. An empty result displays a clear zero-results message.",\n      "priority": "Must Have",\n      "acceptance_criteria": [\n        {\n          "id": "AC-001",\n          "given": "an authenticated operator in account-pilot-a and delivery records across two accounts",\n          "when": "the operator filters status=failed, endpoint=ep-12, event_type=invoice.paid and a valid UTC date range",\n          "then": "only account-pilot-a records matching every filter are returned in the specified order, with at most 50 records per page"\n        },\n        {\n          "id": "AC-002",\n          "given": "an authenticated operator and a date range longer than 30 days or with start greater than or equal to end",\n          "when": "the operator requests delivery history",\n          "then": "the API returns HTTP 400 with code INVALID_DATE_RANGE and the UI explains the allowed range without returning delivery records"\n        }\n      ],\n      "api_contract": "GET /v2/deliveries?status=&endpoint_id=&event_type=&from=&to=&cursor=. Returns HTTP 200 with items and next_cursor; invalid filters return 400. Tenant context comes from the authenticated identity, never a caller-supplied account selector."\n    },\n    {\n      "id": "FR-002",\n      "title": "Inspect delivery evidence",\n      "epic_id": "EP-01",\n      "persona": "Integration Operator",\n      "want": "open the details of a selected delivery",\n      "benefit": "I can determine why delivery failed before deciding whether to replay it.",\n      "description": "Display delivery ID, endpoint ID, event type, UTC timestamp, HTTP status code or the literal network_timeout for a timeout, attempt count and last failure reason. Do not expose raw payload bodies, signing secrets or authorization headers. Show replay eligibility and the supported reason when ineligible.",\n      "priority": "Must Have",\n      "acceptance_criteria": [\n        {\n          "id": "AC-003",\n          "given": "an operator with access to a failed delivery in the same account",\n          "when": "the operator opens its detail view",\n          "then": "all seven specified evidence fields and replay eligibility are displayed, without raw payloads or secret headers"\n        },\n        {\n          "id": "AC-004",\n          "given": "an operator requesting a delivery ID that does not exist in the authenticated account",\n          "when": "the operator opens the detail view",\n          "then": "the API returns HTTP 404 with code DELIVERY_NOT_FOUND and reveals no other account metadata"\n        }\n      ],\n      "api_contract": "GET /v2/deliveries/{delivery_id}. Returns HTTP 200 for an accessible record, otherwise 404. Existing identity checks precede data lookup."\n    },\n    {\n      "id": "FR-003",\n      "title": "Request a single eligible replay",\n      "epic_id": "EP-02",\n      "persona": "Integration Operator",\n      "want": "replay one eligible failed delivery after confirming the action",\n      "benefit": "I can recover a missed webhook without asking an engineer to run a script.",\n      "description": "Require current replay permission and an explicit confirmation displaying delivery ID and endpoint. Accept only network timeouts or HTTP 5xx failures from the previous 30 days. Reject successful, 4xx, too-old or already-running deliveries. Reuse the immutable original payload and signing configuration. A durable acceptance transaction creates an outbox entry and replay_job_id before dispatch.",\n      "priority": "Must Have",\n      "acceptance_criteria": [\n        {\n          "id": "AC-005",\n          "given": "a permitted operator, an eligible same-account HTTP 5xx failure, and a fresh Idempotency-Key",\n          "when": "the operator confirms and sends a replay request",\n          "then": "the API returns HTTP 202 with replay_job_id and queued status, and one durable replay job is accepted"\n        },\n        {\n          "id": "AC-006",\n          "given": "a permitted operator and an HTTP 4xx, successful, older-than-30-days or already-running delivery",\n          "when": "the operator requests replay",\n          "then": "the API returns HTTP 422 with code DELIVERY_NOT_ELIGIBLE and enqueues no replay job"\n        }\n      ],\n      "api_contract": "POST /v2/deliveries/{delivery_id}/replays with required Idempotency-Key and body {\\"reason\\":\\"operator_recovery\\"}. Responses: 202 accepted; 400 missing key; 401 unauthenticated; 403 missing replay permission; 404 inaccessible delivery; 409 key/body conflict; 422 ineligible; 503 failed durable acceptance."\n    },\n    {\n      "id": "FR-004",\n      "title": "Deduplicate replay requests",\n      "epic_id": "EP-02",\n      "persona": "Integration Operator",\n      "want": "safely retry an interrupted replay request",\n      "benefit": "I do not create duplicate replay jobs when my client retries.",\n      "description": "Deduplicate atomically by authenticated account ID, delivery ID and Idempotency-Key for 24 hours from first acceptance. A duplicate identical request returns the original job ID and current status without enqueueing another job. A duplicate key with a different body returns a conflict. Simultaneous duplicate requests are subject to the same atomic guarantee.",\n      "priority": "Must Have",\n      "acceptance_criteria": [\n        {\n          "id": "AC-007",\n          "given": "an accepted replay and its Idempotency-Key within the 24-hour window",\n          "when": "the same account retries the identical request concurrently or sequentially",\n          "then": "every accepted response references the original replay_job_id and exactly one job has been enqueued"\n        },\n        {\n          "id": "AC-008",\n          "given": "an accepted replay key within its 24-hour window",\n          "when": "the same account and delivery reuse the key with a different request body",\n          "then": "the API returns HTTP 409 with code IDEMPOTENCY_CONFLICT and no second job is created"\n        }\n      ],\n      "api_contract": "The replay POST endpoint owns deduplication. The deduplication key includes tenant and delivery identifiers. Keys are not shared across accounts. Expired keys require a fresh eligibility check before any new replay."\n    },\n    {\n      "id": "FR-005",\n      "title": "Observe replay status",\n      "epic_id": "EP-02",\n      "persona": "Integration Operator",\n      "want": "see the current and final state of my replay job",\n      "benefit": "I know whether the webhook recovery succeeded.",\n      "description": "Show queued, running, succeeded or failed plus the last status-update timestamp. Poll every 15 seconds while queued/running and the browser tab is visible. Stop on terminal state or hidden tab; refresh immediately when visible again. A manual refresh control is always available. On a transient polling error, keep the last known state, label it stale and retry on the next normal poll; never claim success from missing data.",\n      "priority": "Must Have",\n      "acceptance_criteria": [\n        {\n          "id": "AC-009",\n          "given": "a visible browser tab showing a queued or running replay",\n          "when": "15 seconds elapse",\n          "then": "the UI requests current status and updates only from a successful response; polling stops when succeeded or failed is returned"\n        },\n        {\n          "id": "AC-010",\n          "given": "a queued replay view that becomes hidden or experiences a failed status request",\n          "when": "the tab is hidden and later visible, or the status request fails",\n          "then": "background polling stops while hidden; visibility restoration triggers immediate refresh; a failed request preserves the last known state and displays a stale-state warning"\n        }\n      ],\n      "api_contract": "GET /v2/replay-jobs/{replay_job_id}. HTTP 200 includes replay_job_id, status, updated_at and sanitized failure_code for failed jobs. Cross-account or absent jobs return 404. State transitions are queued -> running -> succeeded|failed."\n    },\n    {\n      "id": "FR-006",\n      "title": "Manage replay permissions",\n      "epic_id": "EP-03",\n      "persona": "Account Admin",\n      "want": "grant or revoke an operator\'s replay permission within my account",\n      "benefit": "I can control who may initiate a potentially consequential replay.",\n      "description": "The permission screen lists operators in the authenticated admin account and the current replay permission. Require confirmation for grant and revoke. Re-evaluate permission on every replay POST; a revocation must take effect within 60 seconds. A permission change produces an audit event containing admin actor, target operator, account, action and UTC timestamp.",\n      "priority": "Must Have",\n      "acceptance_criteria": [\n        {\n          "id": "AC-011",\n          "given": "an Account Admin and an operator in the same account",\n          "when": "the admin confirms a grant or revoke",\n          "then": "the permission record changes, an audit event is written, and the new permission is enforced on replay requests within 60 seconds"\n        },\n        {\n          "id": "AC-012",\n          "given": "an Integration Operator or Auditor without the Account Admin role",\n          "when": "the user calls the permission-management endpoint",\n          "then": "the API returns HTTP 403 with code ADMIN_ROLE_REQUIRED and makes no permission change"\n        }\n      ],\n      "api_contract": "PUT /v2/operators/{operator_id}/replay-permission with {\\"enabled\\":true|false}. HTTP 200 after durable update and audit; 403 for non-admins; 404 for a target outside the account."\n    },\n    {\n      "id": "FR-007",\n      "title": "Inspect immutable audit history",\n      "epic_id": "EP-03",\n      "persona": "Auditor",\n      "want": "inspect account-scoped delivery and replay audit history",\n      "benefit": "I can reconstruct who initiated a replay and its outcome.",\n      "description": "Provide a read-only audit view filterable by UTC date range, actor ID and delivery ID. Every accepted replay records actor ID, account ID, original delivery ID, replay_job_id, UTC request timestamp and current/final outcome. Terminal updates append events rather than overwriting history. Audit retention is 90 days even though replay eligibility and delivery search are 30 days. Permission-change events are also visible. No export feature is included.",\n      "priority": "Must Have",\n      "acceptance_criteria": [\n        {\n          "id": "AC-013",\n          "given": "an Auditor in an account with accepted replay jobs and terminal outcomes",\n          "when": "the auditor filters the audit view",\n          "then": "only that account\'s audit events appear and every replay is traceable through all six required audit fields"\n        },\n        {\n          "id": "AC-014",\n          "given": "an authenticated Auditor",\n          "when": "the auditor attempts replay, permission modification or audit modification",\n          "then": "each prohibited operation is rejected with HTTP 403 and no write or replay is performed"\n        }\n      ],\n      "api_contract": "GET /v2/audit-events?from=&to=&actor_id=&delivery_id=&cursor=. Returns append-only events for up to 90 days. The public pilot API exposes no audit update or delete operation."\n    },\n    {\n      "id": "FR-008",\n      "title": "Enforce account isolation",\n      "epic_id": "EP-03",\n      "persona": "Account Admin",\n      "want": "have account boundaries enforced on every delivery, replay, permission and audit operation",\n      "benefit": "my account\'s records remain inaccessible to another account.",\n      "description": "Derive account scope exclusively from the authenticated identity. Apply scope checks in both service authorization and data queries. Never trust an account ID from the request body or query string. Use non-disclosing 404 responses for inaccessible record IDs and 403 for prohibited actions on accessible records. Audit internal authorization failures without logging payload secrets.",\n      "priority": "Must Have",\n      "acceptance_criteria": [\n        {\n          "id": "AC-015",\n          "given": "a valid user session from account-pilot-a and a delivery or replay job belonging only to account-pilot-b",\n          "when": "the user requests that identifier or supplies a forged account selector",\n          "then": "the API returns HTTP 404 or rejects the unsupported selector and returns no account-pilot-b data"\n        },\n        {\n          "id": "AC-016",\n          "given": "a cross-account test matrix covering delivery list, detail, replay, permission management and audit history",\n          "when": "the isolation suite executes with all three pilot account identities",\n          "then": "zero cross-account reads or writes succeed and no replay job is enqueued by a cross-account request"\n        }\n      ],\n      "api_contract": "All /v2 console routes use authenticated account scope. API authorization is mandatory even when the corresponding UI action is hidden."\n    }\n  ],\n  "nfrs": [\n    {\n      "id": "NFR-001",\n      "category": "Performance",\n      "requirement": "The delivery-list API must respond in less than 800 ms at p95 under the declared pilot workload.",\n      "target": "p95 < 800 ms with 500 concurrent operators and 100,000 delivery records per account.",\n      "verification": "Run a 30-minute steady-state load test after five-minute warmup, using realistic filter combinations; report p50, p95, p99, errors and sample count.",\n      "owner": "Ravi Menon",\n      "related_requirements": [\n        "FR-001"\n      ]\n    },\n    {\n      "id": "NFR-002",\n      "category": "Audit retention",\n      "requirement": "Accepted replay and permission audit events must remain queryable for 90 days and append-only throughout that interval.",\n      "target": "90-day retention; 100% required audit-field completeness for accepted replay jobs.",\n      "verification": "Retention-boundary test, append-only permission check and daily job-to-audit reconciliation.",\n      "owner": "Isha Shah",\n      "related_requirements": [\n        "FR-003",\n        "FR-006",\n        "FR-007"\n      ]\n    },\n    {\n      "id": "NFR-003",\n      "category": "Browser compatibility",\n      "requirement": "The pilot console must support desktop Chrome 140 and Edge 140 at viewport widths of 1280 pixels and above.",\n      "target": "All pilot acceptance scenarios pass in both specified desktop browser versions. Mobile support is explicitly excluded.",\n      "verification": "Cross-browser regression suite on the pinned synthetic acceptance environment. These versions are fictional project test targets, not a current-browser recommendation.",\n      "owner": "Ravi Menon",\n      "related_requirements": [\n        "FR-001",\n        "FR-002",\n        "FR-005",\n        "FR-006",\n        "FR-007"\n      ]\n    },\n    {\n      "id": "NFR-004",\n      "category": "Security and privacy",\n      "requirement": "Use TLS 1.2 or higher for console-to-API communication; redact raw payloads, signing secrets and authorization headers from UI and application logs.",\n      "target": "Zero forbidden secret values in the security test corpus; all five route families enforce account isolation.",\n      "verification": "TLS configuration check, secret-canary scanning and negative authorization tests before launch.",\n      "owner": "Isha Shah",\n      "related_requirements": [\n        "FR-002",\n        "FR-003",\n        "FR-008"\n      ]\n    }\n  ],\n  "architecture": {\n    "nodes": [\n      {\n        "id": "OP",\n        "label": "Integration Operator / Account Admin / Auditor"\n      },\n      {\n        "id": "UI",\n        "label": "Desktop Console: filters, detail, replay, audit"\n      },\n      {\n        "id": "AUTH",\n        "label": "Existing Customer-Account Identity Service"\n      },\n      {\n        "id": "API",\n        "label": "Delivery API v2: authorization and tenant scope"\n      },\n      {\n        "id": "DB",\n        "label": "Account-scoped Delivery Store: 30-day search"\n      },\n      {\n        "id": "DEDUP",\n        "label": "Atomic 24-hour Idempotency + Outbox"\n      },\n      {\n        "id": "WORKER",\n        "label": "Core Events Replay Worker"\n      },\n      {\n        "id": "ENDPOINT",\n        "label": "Existing Customer Webhook Endpoint"\n      },\n      {\n        "id": "JOB",\n        "label": "Replay Job Store: queued / running / succeeded / failed"\n      },\n      {\n        "id": "AUDIT",\n        "label": "Append-only Audit Store: 90 days"\n      },\n      {\n        "id": "KPI",\n        "label": "Daily Pilot KPI Reconciliation"\n      }\n    ],\n    "edges": [\n      {\n        "from": "OP",\n        "to": "UI",\n        "label": "Use role-appropriate controls",\n        "evidence": [\n          "FR-001",\n          "FR-006",\n          "FR-007"\n        ]\n      },\n      {\n        "from": "UI",\n        "to": "AUTH",\n        "label": "Authenticate and obtain account identity",\n        "evidence": [\n          "FR-008"\n        ]\n      },\n      {\n        "from": "UI",\n        "to": "API",\n        "label": "HTTPS /v2 requests with authenticated identity",\n        "evidence": [\n          "FR-001",\n          "FR-008",\n          "NFR-004"\n        ]\n      },\n      {\n        "from": "API",\n        "to": "AUTH",\n        "label": "Check current replay/admin permission",\n        "evidence": [\n          "FR-003",\n          "FR-006"\n        ]\n      },\n      {\n        "from": "API",\n        "to": "DB",\n        "label": "Tenant-scoped list and detail queries",\n        "evidence": [\n          "FR-001",\n          "FR-002",\n          "FR-008"\n        ]\n      },\n      {\n        "from": "API",\n        "to": "DEDUP",\n        "label": "Eligibility + atomic accept or 409 conflict",\n        "evidence": [\n          "FR-003",\n          "FR-004"\n        ]\n      },\n      {\n        "from": "DEDUP",\n        "to": "JOB",\n        "label": "Persist replay_job_id and queued status",\n        "evidence": [\n          "FR-003"\n        ]\n      },\n      {\n        "from": "DEDUP",\n        "to": "AUDIT",\n        "label": "Durable acceptance audit/outbox transaction",\n        "evidence": [\n          "FR-003",\n          "FR-007"\n        ]\n      },\n      {\n        "from": "DEDUP",\n        "to": "WORKER",\n        "label": "Dispatch accepted job once",\n        "evidence": [\n          "FR-004"\n        ]\n      },\n      {\n        "from": "WORKER",\n        "to": "ENDPOINT",\n        "label": "Original payload and existing signing configuration",\n        "evidence": [\n          "FR-003",\n          "DEC-02"\n        ]\n      },\n      {\n        "from": "WORKER",\n        "to": "JOB",\n        "label": "Append state transition and sanitized result",\n        "evidence": [\n          "FR-005"\n        ]\n      },\n      {\n        "from": "WORKER",\n        "to": "AUDIT",\n        "label": "Append final outcome",\n        "evidence": [\n          "FR-007"\n        ]\n      },\n      {\n        "from": "UI",\n        "to": "API",\n        "label": "Visible active-job poll every 15 seconds",\n        "evidence": [\n          "FR-005",\n          "DEC-03"\n        ]\n      },\n      {\n        "from": "API",\n        "to": "JOB",\n        "label": "Read account-scoped job status",\n        "evidence": [\n          "FR-005",\n          "FR-008"\n        ]\n      },\n      {\n        "from": "API",\n        "to": "AUDIT",\n        "label": "Read-only 90-day audit query",\n        "evidence": [\n          "FR-007",\n          "NFR-002"\n        ]\n      },\n      {\n        "from": "AUDIT",\n        "to": "KPI",\n        "label": "Daily completeness reconciliation",\n        "evidence": [\n          "DEC-05",\n          "NFR-002"\n        ]\n      }\n    ]\n  }\n}\n'}, {'name': '02-product-brief.md', 'role': 'supporting_source', 'text': "# RelayOps - Detailed Product Brief\n\nSYNTHETIC SOURCE MATERIAL. Not user-approved. Product scope: relayops-pilot-v1.\n\nFictional product scenario. Product-team characters, accounts, budgets and measurements are synthetic; the document author and actual reviewer are user-supplied identities.\n\nA tenant-isolated desktop console that lets integration operators investigate failed webhook deliveries and replay eligible events without an engineering-owned script. A three-account pilot covers investigation, permission management, replay orchestration and audit history; the existing identity service and Delivery API v2 remain the systems of record.\n\nSupport currently collects an event identifier, asks an engineer to inspect logs, waits for an engineering script to replay the event, and asks again for the result. This creates repeated handoffs, weak operator visibility and inconsistent replay audit records.\n\n## Business goal\nReduce the median elapsed time from a failed-delivery support report to a confirmed replay result from a synthetic baseline of 45 minutes to at most 15 minutes during the four-week pilot.\n\n## User goal\nEnable authorized Integration Operators to find failures, inspect evidence, start one eligible replay and see its final outcome without requesting script access.\n\n## Pilot delivery\n- budget: Synthetic pilot engineering budget: USD 48,000, including a USD 3,000 infrastructure ceiling for the four-week pilot.\n- team: One PM, one designer, two backend engineers, one frontend engineer and one QA engineer; security and identity owners provide part-time review.\n- rollout: Enable the feature for exactly three fictional accounts, account-pilot-a, account-pilot-b and account-pilot-c, on 2026-10-12 after go/no-go approval.\n- rollback: Disable replay controls using the per-account feature flag; continue read-only inspection and let already accepted jobs finish. Do not delete queued jobs or audit records.\n- support: Core Events owns worker incidents; Identity owns authorization incidents; Security owns audit gaps. Maya coordinates the pilot incident review.\n\n## Personas\n### Integration Operator\n- need: Investigate and replay eligible failed deliveries in the operator's own account.\n- workaround: Open a support ticket and ask engineering to run an internal replay script.\n- permissions: Read delivery records; replay only when an Account Admin has explicitly granted replay permission.\n\n### Account Admin\n- need: Control which operators may initiate replay within the admin's account.\n- workaround: Ask the identity team to change role assignments manually.\n- permissions: Grant or revoke operator replay permission; no cross-account administration.\n\n### Auditor\n- need: Inspect delivery history and replay audit evidence within the auditor's account.\n- workaround: Request CSV extracts from engineering and correlate ticket IDs manually.\n- permissions: Read delivery and audit history only; cannot replay or change permissions.\n\n## Success metrics\n### Median resolution time\n- baseline: 45 minutes across 20 fictional historical tickets\n- target: At most 15 minutes\n- window: Four-week pilot, 2026-10-12 through 2026-11-08\n- measurement: Median of support_reported_at to replay_terminal_at for eligible resolved pilot tickets; report unresolved-ticket count separately to avoid survivor bias.\n- owner: Noor Ali, Product Analytics\n\n### Self-service completion rate\n- baseline: 0% in the fictional manual process\n- target: At least 80% of eligible replay incidents completed without an engineer running a script\n- window: Same four-week pilot\n- measurement: Eligible completed incidents with operator-started replay divided by all eligible completed incidents; exclude ineligible 4xx failures and publish the exclusion count.\n- owner: Noor Ali, Product Analytics\n\n### Audit completeness\n- baseline: 60% of 20 fictional historical tickets have a traceable actor and outcome\n- target: 100% of accepted replay jobs have all required audit fields and a terminal or current state\n- window: Daily checks throughout pilot\n- measurement: Reconcile accepted replay_job_id values against append-only audit events; any missing identifier or actor fails release readiness.\n- owner: Isha Shah, Security Engineering\n"}, {'name': '03-api-and-acceptance-catalog.md', 'role': 'supporting_source', 'text': '# RelayOps - API and Acceptance Catalog\n\nSYNTHETIC SOURCE MATERIAL. Not user-approved. Product scope: relayops-pilot-v1.\n\n## FR-001 - Filter delivery history\n\nProvide an account-scoped delivery list. Combine supplied filters with AND. Use UTC ISO 8601 date bounds, inclusive start and exclusive end. Limit the selected interval and record age to the previous 30 days. Paginate 50 records per page, ordered by timestamp descending and delivery ID descending as the tie-breaker. An empty result displays a clear zero-results message.\n\nGET /v2/deliveries?status=&endpoint_id=&event_type=&from=&to=&cursor=. Returns HTTP 200 with items and next_cursor; invalid filters return 400. Tenant context comes from the authenticated identity, never a caller-supplied account selector.\n\nPriority: Must Have\n\nAC-001\nGIVEN an authenticated operator in account-pilot-a and delivery records across two accounts\nWHEN the operator filters status=failed, endpoint=ep-12, event_type=invoice.paid and a valid UTC date range\nTHEN only account-pilot-a records matching every filter are returned in the specified order, with at most 50 records per page\n\nAC-002\nGIVEN an authenticated operator and a date range longer than 30 days or with start greater than or equal to end\nWHEN the operator requests delivery history\nTHEN the API returns HTTP 400 with code INVALID_DATE_RANGE and the UI explains the allowed range without returning delivery records\n\n## FR-002 - Inspect delivery evidence\n\nDisplay delivery ID, endpoint ID, event type, UTC timestamp, HTTP status code or the literal network_timeout for a timeout, attempt count and last failure reason. Do not expose raw payload bodies, signing secrets or authorization headers. Show replay eligibility and the supported reason when ineligible.\n\nGET /v2/deliveries/{delivery_id}. Returns HTTP 200 for an accessible record, otherwise 404. Existing identity checks precede data lookup.\n\nPriority: Must Have\n\nAC-003\nGIVEN an operator with access to a failed delivery in the same account\nWHEN the operator opens its detail view\nTHEN all seven specified evidence fields and replay eligibility are displayed, without raw payloads or secret headers\n\nAC-004\nGIVEN an operator requesting a delivery ID that does not exist in the authenticated account\nWHEN the operator opens the detail view\nTHEN the API returns HTTP 404 with code DELIVERY_NOT_FOUND and reveals no other account metadata\n\n## FR-003 - Request a single eligible replay\n\nRequire current replay permission and an explicit confirmation displaying delivery ID and endpoint. Accept only network timeouts or HTTP 5xx failures from the previous 30 days. Reject successful, 4xx, too-old or already-running deliveries. Reuse the immutable original payload and signing configuration. A durable acceptance transaction creates an outbox entry and replay_job_id before dispatch.\n\nPOST /v2/deliveries/{delivery_id}/replays with required Idempotency-Key and body {"reason":"operator_recovery"}. Responses: 202 accepted; 400 missing key; 401 unauthenticated; 403 missing replay permission; 404 inaccessible delivery; 409 key/body conflict; 422 ineligible; 503 failed durable acceptance.\n\nPriority: Must Have\n\nAC-005\nGIVEN a permitted operator, an eligible same-account HTTP 5xx failure, and a fresh Idempotency-Key\nWHEN the operator confirms and sends a replay request\nTHEN the API returns HTTP 202 with replay_job_id and queued status, and one durable replay job is accepted\n\nAC-006\nGIVEN a permitted operator and an HTTP 4xx, successful, older-than-30-days or already-running delivery\nWHEN the operator requests replay\nTHEN the API returns HTTP 422 with code DELIVERY_NOT_ELIGIBLE and enqueues no replay job\n\n## FR-004 - Deduplicate replay requests\n\nDeduplicate atomically by authenticated account ID, delivery ID and Idempotency-Key for 24 hours from first acceptance. A duplicate identical request returns the original job ID and current status without enqueueing another job. A duplicate key with a different body returns a conflict. Simultaneous duplicate requests are subject to the same atomic guarantee.\n\nThe replay POST endpoint owns deduplication. The deduplication key includes tenant and delivery identifiers. Keys are not shared across accounts. Expired keys require a fresh eligibility check before any new replay.\n\nPriority: Must Have\n\nAC-007\nGIVEN an accepted replay and its Idempotency-Key within the 24-hour window\nWHEN the same account retries the identical request concurrently or sequentially\nTHEN every accepted response references the original replay_job_id and exactly one job has been enqueued\n\nAC-008\nGIVEN an accepted replay key within its 24-hour window\nWHEN the same account and delivery reuse the key with a different request body\nTHEN the API returns HTTP 409 with code IDEMPOTENCY_CONFLICT and no second job is created\n\n## FR-005 - Observe replay status\n\nShow queued, running, succeeded or failed plus the last status-update timestamp. Poll every 15 seconds while queued/running and the browser tab is visible. Stop on terminal state or hidden tab; refresh immediately when visible again. A manual refresh control is always available. On a transient polling error, keep the last known state, label it stale and retry on the next normal poll; never claim success from missing data.\n\nGET /v2/replay-jobs/{replay_job_id}. HTTP 200 includes replay_job_id, status, updated_at and sanitized failure_code for failed jobs. Cross-account or absent jobs return 404. State transitions are queued -> running -> succeeded|failed.\n\nPriority: Must Have\n\nAC-009\nGIVEN a visible browser tab showing a queued or running replay\nWHEN 15 seconds elapse\nTHEN the UI requests current status and updates only from a successful response; polling stops when succeeded or failed is returned\n\nAC-010\nGIVEN a queued replay view that becomes hidden or experiences a failed status request\nWHEN the tab is hidden and later visible, or the status request fails\nTHEN background polling stops while hidden; visibility restoration triggers immediate refresh; a failed request preserves the last known state and displays a stale-state warning\n\n## FR-006 - Manage replay permissions\n\nThe permission screen lists operators in the authenticated admin account and the current replay permission. Require confirmation for grant and revoke. Re-evaluate permission on every replay POST; a revocation must take effect within 60 seconds. A permission change produces an audit event containing admin actor, target operator, account, action and UTC timestamp.\n\nPUT /v2/operators/{operator_id}/replay-permission with {"enabled":true|false}. HTTP 200 after durable update and audit; 403 for non-admins; 404 for a target outside the account.\n\nPriority: Must Have\n\nAC-011\nGIVEN an Account Admin and an operator in the same account\nWHEN the admin confirms a grant or revoke\nTHEN the permission record changes, an audit event is written, and the new permission is enforced on replay requests within 60 seconds\n\nAC-012\nGIVEN an Integration Operator or Auditor without the Account Admin role\nWHEN the user calls the permission-management endpoint\nTHEN the API returns HTTP 403 with code ADMIN_ROLE_REQUIRED and makes no permission change\n\n## FR-007 - Inspect immutable audit history\n\nProvide a read-only audit view filterable by UTC date range, actor ID and delivery ID. Every accepted replay records actor ID, account ID, original delivery ID, replay_job_id, UTC request timestamp and current/final outcome. Terminal updates append events rather than overwriting history. Audit retention is 90 days even though replay eligibility and delivery search are 30 days. Permission-change events are also visible. No export feature is included.\n\nGET /v2/audit-events?from=&to=&actor_id=&delivery_id=&cursor=. Returns append-only events for up to 90 days. The public pilot API exposes no audit update or delete operation.\n\nPriority: Must Have\n\nAC-013\nGIVEN an Auditor in an account with accepted replay jobs and terminal outcomes\nWHEN the auditor filters the audit view\nTHEN only that account\'s audit events appear and every replay is traceable through all six required audit fields\n\nAC-014\nGIVEN an authenticated Auditor\nWHEN the auditor attempts replay, permission modification or audit modification\nTHEN each prohibited operation is rejected with HTTP 403 and no write or replay is performed\n\n## FR-008 - Enforce account isolation\n\nDerive account scope exclusively from the authenticated identity. Apply scope checks in both service authorization and data queries. Never trust an account ID from the request body or query string. Use non-disclosing 404 responses for inaccessible record IDs and 403 for prohibited actions on accessible records. Audit internal authorization failures without logging payload secrets.\n\nAll /v2 console routes use authenticated account scope. API authorization is mandatory even when the corresponding UI action is hidden.\n\nPriority: Must Have\n\nAC-015\nGIVEN a valid user session from account-pilot-a and a delivery or replay job belonging only to account-pilot-b\nWHEN the user requests that identifier or supplies a forged account selector\nTHEN the API returns HTTP 404 or rejects the unsupported selector and returns no account-pilot-b data\n\nAC-016\nGIVEN a cross-account test matrix covering delivery list, detail, replay, permission management and audit history\nWHEN the isolation suite executes with all three pilot account identities\nTHEN zero cross-account reads or writes succeed and no replay job is enqueued by a cross-account request\n'}, {'name': '04-nfr-security-and-operations.md', 'role': 'supporting_source', 'text': '# RelayOps - NFR and Operations Decisions\n\nSYNTHETIC SOURCE MATERIAL. Not user-approved. Product scope: relayops-pilot-v1.\n\n## NFR-001 - Performance\n- requirement: The delivery-list API must respond in less than 800 ms at p95 under the declared pilot workload.\n- target: p95 < 800 ms with 500 concurrent operators and 100,000 delivery records per account.\n- verification: Run a 30-minute steady-state load test after five-minute warmup, using realistic filter combinations; report p50, p95, p99, errors and sample count.\n- owner: Ravi Menon\n- related_requirements: [\'FR-001\']\n\n## NFR-002 - Audit retention\n- requirement: Accepted replay and permission audit events must remain queryable for 90 days and append-only throughout that interval.\n- target: 90-day retention; 100% required audit-field completeness for accepted replay jobs.\n- verification: Retention-boundary test, append-only permission check and daily job-to-audit reconciliation.\n- owner: Isha Shah\n- related_requirements: [\'FR-003\', \'FR-006\', \'FR-007\']\n\n## NFR-003 - Browser compatibility\n- requirement: The pilot console must support desktop Chrome 140 and Edge 140 at viewport widths of 1280 pixels and above.\n- target: All pilot acceptance scenarios pass in both specified desktop browser versions. Mobile support is explicitly excluded.\n- verification: Cross-browser regression suite on the pinned synthetic acceptance environment. These versions are fictional project test targets, not a current-browser recommendation.\n- owner: Ravi Menon\n- related_requirements: [\'FR-001\', \'FR-002\', \'FR-005\', \'FR-006\', \'FR-007\']\n\n## NFR-004 - Security and privacy\n- requirement: Use TLS 1.2 or higher for console-to-API communication; redact raw payloads, signing secrets and authorization headers from UI and application logs.\n- target: Zero forbidden secret values in the security test corpus; all five route families enforce account isolation.\n- verification: TLS configuration check, secret-canary scanning and negative authorization tests before launch.\n- owner: Isha Shah\n- related_requirements: [\'FR-002\', \'FR-003\', \'FR-008\']\n\n## Dependencies\n[\n  {\n    "name": "Delivery API v2",\n    "owner": "Leo Chen, Core Events",\n    "status": "Existing API; pilot contract additions due 2026-09-25",\n    "risk": "Delayed status-query support prevents end-to-end replay observation.",\n    "mitigation": "Contract tests at integration start; feature flag remains off if readiness fails."\n  },\n  {\n    "name": "Replay-worker API",\n    "owner": "Leo Chen, Core Events",\n    "status": "Synthetic commitment: staging available 2026-09-25",\n    "risk": "Worker readiness is a critical-path dependency.",\n    "mitigation": "Daily contract smoke test from 2026-09-25; launch requires successful enqueue-to-terminal test."\n  },\n  {\n    "name": "Customer-account identity service",\n    "owner": "Omar Khan, Identity Team",\n    "status": "Existing service; replay-permission endpoint contract signed 2026-09-11",\n    "risk": "Stale role propagation could retain revoked access.",\n    "mitigation": "Every replay authorization checks current permission; revocations take effect within 60 seconds."\n  },\n  {\n    "name": "Append-only audit store",\n    "owner": "Isha Shah, Security Engineering",\n    "status": "Existing storage; retention policy configured by 2026-09-28",\n    "risk": "Audit write failure could create an untraceable replay.",\n    "mitigation": "Atomic outbox transaction records acceptance before dispatch; do not accept replay if transaction fails."\n  }\n]\n\n## Rollback\nDisable replay controls using the per-account feature flag; continue read-only inspection and let already accepted jobs finish. Do not delete queued jobs or audit records.\n'}, {'name': '05-decision-workshop-transcript.md', 'role': 'supporting_source', 'text': '# RelayOps - Decision Workshop, 2026-09-11\n\nSYNTHETIC SOURCE MATERIAL. Not user-approved. Product scope: relayops-pilot-v1.\n\nParticipants: Maya Sen (PM), Aditi Rao (Engineering), Leo Chen (Core Events), Isha Shah (Security), Noor Ali (Analytics), Elena Park (Design), Ravi Menon (QA). All are fictional.\n\n[09:00] Maya: We are resolving the discovery gaps today. This release is a pilot, not general availability. Three accounts only. Do not carry forward unresolved statements from the older discovery notes as if they were current decisions.\n[09:04] Leo: I previously said worker availability was unknown. For this synthetic scenario, staging is now committed for September 25, 2026. Record the commitment and its critical-path risk separately.\n[09:07] Aditi: We should not replay all failures. Only timeouts and 5xx within 30 days. A 4xx can indicate invalid business data, and automatic replay would be unsafe. Successful or running deliveries are also ineligible.\n[09:10] Maya: Agreed. Treat that as DEC-01. Bulk replay remains excluded.\n[09:12] Leo: Deduplication is scoped to account, delivery and the request key, for 24 hours. The same body returns the same job ID; a changed body is a 409. Simultaneous requests must obey the same rule. A new queue entry must never precede durable acceptance and its audit/outbox record.\n[09:16] Isha: Auditors only read. Every replay needs actor, account, original delivery, replay job, request time and outcome. Keep audit events 90 days, while the delivery search window stays 30 days. These are different retention purposes, not conflicting requirements.\n[09:20] Elena: Five-second polling would create needless requests. We agree on 15 seconds while an active job is visible, stopping when hidden or terminal. A failed status request must show stale state rather than success. Manual refresh is available.\n[09:24] Noor: I own the pilot dashboard. The 45-minute baseline is synthetic. Our target is at most 15 minutes median. Report unresolved ticket counts too, so we do not make the metric look better by dropping slow unresolved cases.\n[09:28] Maya: Customer export is excluded. The auditor can use the read-only audit view. We are not promising CSV formula preservation or spreadsheet behavior for this product.\n[09:31] Ravi: Performance acceptance is p95 less than 800 ms at 500 concurrent operators, with 100,000 records per account. Thirty minutes of steady-state load after warmup. Do not round any of these numbers.\n[09:34] Isha: TLS 1.2 or higher. No payload bodies, signing secrets or authorization headers in the UI or app logs. Account scope comes from identity, never a request selector. Negative authorization tests are a launch gate.\n[09:38] Maya: Requirements review September 18, design September 21, development September 22, integration September 28, QA October 5 and pilot launch October 12. Pilot review November 9. The current source catalog contains the complete field-level decisions.\n[09:42] Aditi: These are source proposals for the capstone, not an actual user approval. The PRD Genie reviewer must inspect extracted evidence and explicitly approve before the generator can run.\n'}, {'name': '06-stakeholder-notes-and-resolution-register.md', 'role': 'supporting_source', 'text': '# RelayOps - Stakeholder Notes and Resolutions\n\nSYNTHETIC SOURCE MATERIAL. Not user-approved. Product scope: relayops-pilot-v1.\n\n## DEC-01\nQuestion: Which delivery failures are eligible?\nResolution: Only network timeouts and HTTP 5xx failures from the previous 30 days are eligible. HTTP 4xx, successful and already-running deliveries are not eligible.\nOwner: Maya Sen\nDate: 2026-09-11\n\n## DEC-02\nQuestion: What happens when a key is reused?\nResolution: Within 24 hours, the same account, delivery and Idempotency-Key with an identical body returns the original replay_job_id without another enqueue. Reusing the key with a different body returns HTTP 409.\nOwner: Leo Chen\nDate: 2026-09-11\n\n## DEC-03\nQuestion: How often does job status refresh?\nResolution: The UI polls job status every 15 seconds only while the job is queued or running and the tab is visible. Polling stops on terminal status or hidden tab and refreshes immediately when the tab becomes visible. Manual refresh is available.\nOwner: Aditi Rao\nDate: 2026-09-11\n\n## DEC-04\nQuestion: Is customer-facing export included?\nResolution: No customer-facing export in the pilot. Auditors use the account-scoped on-screen audit view.\nOwner: Maya Sen\nDate: 2026-09-11\n\n## DEC-05\nQuestion: Who owns KPI reporting?\nResolution: Noor Ali owns daily dashboard reconciliation and the final four-week pilot report.\nOwner: Maya Sen\nDate: 2026-09-11\n\n## DEC-06\nQuestion: Is the worker availability still unknown?\nResolution: The earlier discovery uncertainty is superseded by the synthetic Core Events commitment of staging availability on 2026-09-25. This is a sample scenario decision, not a real team commitment.\nOwner: Leo Chen\nDate: 2026-09-11\n\n## Scope exclusions\n- Bulk replay and scheduled replay\n- Creating or editing webhook endpoints\n- New webhook signing algorithms\n- Mobile and native applications\n- AI-generated failure explanations\n- Customer-facing CSV or spreadsheet export in the pilot\n\n## Explicit assumptions\n[\n  {\n    "statement": "The three fictional pilot accounts use the existing customer-account identity service and have no external SSO migration during this pilot.",\n    "owner": "Omar Khan, Identity Team",\n    "validation": "Verified in the synthetic pilot-readiness inventory on 2026-09-11."\n  },\n  {\n    "statement": "A replay reuses the original immutable event payload and existing signing configuration; it does not create or edit an event.",\n    "owner": "Leo Chen, Core Events",\n    "validation": "Recorded as decision DEC-02 and included in replay contract review."\n  },\n  {\n    "statement": "The synthetic workload of 100,000 delivery records per account and 500 concurrent operators is sufficient for pilot capacity testing.",\n    "owner": "Aditi Rao, Engineering Lead",\n    "validation": "Explicit pilot sizing decision; expansion beyond this envelope requires a new capacity review."\n  }\n]\n\n## Milestones\n[\n  {\n    "milestone": "Requirements and architecture review",\n    "date": "2026-09-18",\n    "owner": "Maya Sen and Aditi Rao",\n    "exit": "Reviewer approves source-backed requirements, API contracts and scope decisions."\n  },\n  {\n    "milestone": "Design Complete",\n    "date": "2026-09-21",\n    "owner": "Elena Park, Product Design",\n    "exit": "Desktop interaction and permission-error designs signed off."\n  },\n  {\n    "milestone": "Development Start",\n    "date": "2026-09-22",\n    "owner": "Aditi Rao",\n    "exit": "Sprint backlog accepted and mocked API contracts available."\n  },\n  {\n    "milestone": "Integration ready",\n    "date": "2026-09-28",\n    "owner": "Leo Chen",\n    "exit": "Identity, worker and audit integration contract tests pass."\n  },\n  {\n    "milestone": "QA / Testing",\n    "date": "2026-10-05",\n    "owner": "Ravi Menon, QA Lead",\n    "exit": "Functional, tenant-isolation, replay-deduplication, browser and capacity tests pass."\n  },\n  {\n    "milestone": "Launch",\n    "date": "2026-10-12",\n    "owner": "Maya Sen",\n    "exit": "Go/no-go approval; three account feature flags enabled; monitoring and rollback staffed."\n  },\n  {\n    "milestone": "Pilot review",\n    "date": "2026-11-09",\n    "owner": "Noor Ali",\n    "exit": "Four-week KPI report, incident review and rollout recommendation reviewed."\n  }\n]\n'}, {'name': '07-prd-template.md', 'role': 'template', 'text': '# Product Requirements Document (PRD) Template\n\n## 1. Product Overview\n- **Product Name:**\n- **Document Version:**\n- **Author:**\n- **Date:**\n- **Status:** [Draft / In Review / Approved]\n\n## 2. Goals and Objectives\n- **Business Goal:** What business outcome does this feature drive?\n- **User Goal:** What problem does this solve for the user?\n- **Success Metrics:** How will we measure success? (list 2-3 KPIs)\n\n## 3. User Personas\nFor each persona, describe:\n- **Name / Role:**\n- **Key Need:**\n- **Current Workaround:**\n\n## 4. Feature Requirements\n\n### 4.1 Functional Requirements\n| ID | Requirement | Priority (Must/Should/Nice) | Source |\n|----|-------------|---------------------------|--------|\n| FR-001 | | | |\n| FR-002 | | | |\n\n### 4.2 Non-Functional Requirements\n| ID | Requirement | Category | Target |\n|----|-------------|----------|--------|\n| NFR-001 | | Performance | |\n| NFR-002 | | Security | |\n\n## 5. Acceptance Criteria\nFor each key feature, list specific testable criteria:\n- **Feature X:**\n  - [ ] Criteria 1\n  - [ ] Criteria 2\n\n## 6. Out of Scope\nList what is explicitly NOT included in this release.\n\n## 7. Dependencies\n| Dependenc